begin;
set local search_path=public,extensions;
select no_plan();
insert into auth.users(id,email)values('c1000000-0000-0000-0000-000000000001','onboard-one@test.invalid'),('c1000000-0000-0000-0000-000000000002','onboard-two@test.invalid');
create function pg_temp.fail_test_property()returns trigger language plpgsql as $$begin if new.name='Forced property failure'then raise exception 'Test property failure';end if;return new;end$$;
create trigger qa_force_property_failure before insert on public.properties for each row execute function pg_temp.fail_test_property();
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"c1000000-0000-0000-0000-000000000001","role":"authenticated"}',true);
select throws_ok($$select public.create_hotel_workspace('c2000000-0000-0000-0000-000000000001','Atomic Audit Business','Audit Hotel','hotel','Invalid/Zone','INR')$$,'22023',null,'Invalid timezone rejected before creating business');
select is((select count(*)::int from public.tenants where name='Atomic Audit Business'),0,'Invalid setup leaves no business');
select throws_ok($$select public.create_hotel_workspace('c2000000-0000-0000-0000-000000000001','Rollback Audit Business','Forced property failure','hotel','UTC','INR')$$,'P0001','Test property failure','Failure after tenant creation aborts whole onboarding');
select is((select count(*)::int from public.tenants where name='Rollback Audit Business'),0,'Property failure leaves no orphaned business');
select set_config('test.atomic_workspace',public.create_hotel_workspace('c2000000-0000-0000-0000-000000000001','Atomic Audit Business','Audit Hotel','hotel','Asia/Kolkata','INR')::text,true);
select is(public.create_hotel_workspace('c2000000-0000-0000-0000-000000000001','Atomic Audit Business','Audit Hotel','hotel','Asia/Kolkata','INR'),current_setting('test.atomic_workspace')::jsonb,'Retry returns same business and hotel');
select is((select count(*)::int from public.tenants where name='Atomic Audit Business'),1,'Repeated submission creates one business');
select is((select count(*)::int from public.properties where name='Audit Hotel'),1,'Repeated submission creates one hotel');
select is((select role from public.tenant_memberships where tenant_id=(current_setting('test.atomic_workspace')::jsonb->>'tenant_id')::uuid and user_id=auth.uid()),'owner','Session user becomes business owner');
select is((select currency::text from public.properties where id=(current_setting('test.atomic_workspace')::jsonb->>'property_id')::uuid),'INR','Chosen hotel currency saved');
select ok(exists(select 1 from public.property_settings where property_id=(current_setting('test.atomic_workspace')::jsonb->>'property_id')::uuid),'Hotel operational settings initialized');
select throws_ok($$select public.create_hotel_workspace('c2000000-0000-0000-0000-000000000001','Changed Business','Audit Hotel','hotel','UTC','USD')$$,'22023',null,'Same request cannot be reused with changed details');
select set_config('request.jwt.claims','{"sub":"c1000000-0000-0000-0000-000000000002","role":"authenticated"}',true);
select lives_ok($$select public.create_hotel_workspace('c2000000-0000-0000-0000-000000000001','Other Atomic Business','Other Audit Hotel','hotel','UTC','USD')$$,'Another actor has independent request scope');
select is_empty($$select id from public.tenants where name='Atomic Audit Business'$$,'Second owner cannot see first business');
select throws_ok($$select *from private.workspace_onboarding_requests$$,'42501',null,'Clients cannot read onboarding command records');
reset role;
set local role anon;
select throws_ok($$select public.create_hotel_workspace('c2000000-0000-0000-0000-000000000002','Anon Business','Anon Hotel','hotel','UTC','INR')$$,'42501',null,'Anonymous callers cannot onboard');
select *from finish();
rollback;
